     * adds nothing to the sum of squares, and the block peak is
     * max(hi, -lo) which is non-negative already, so widening the
     * range by a zero cannot move it. */
    r12 = 0;
    r5 = DSP4_BLOCK_SIZE;
    lcntr = r5; do .gk_lp_C1_GAIN_28 until lce;
        r0 = dm(i0, 1);
        mrb = r0 * r1 (ssi);
        r13 = max(r13, r12);          /* meter, one sample behind */
        mrf = mrf + r12 * r12 (ssi);
        r15 = min(r15, r12);
        r12 = mr1b;                   /* WIDE post-trim, Q8.24 */
        mrb = mrb + r6 * r7 (ssi);
        r8 = mr0b;
        r2 = mr1b;
        r8 = lshift r8 by -28;
        r9 = lshift r2 by 4;
        r0 = r8 or r9;
        r8 = ashift r2 by -28;
        r9 = ashift r0 by -31;
        r11 = ashift r2 by -31;
        r11 = r10 xor r11;
        comp(r8, r9);
        if ne r0 = r11;
        dm(i1, 1) = r0;
.gk_lp_C1_GAIN_28:
        dm(i4, 1) = r0;
    dm(_tap_post_trim_C1_GAIN_28) = r0;   /* linkage scalars */
    dm(_buf_C1_GAIN_28) = r0;
    /* the last sample's meter ops, outside the loop */
    r13 = max(r13, r12);
    mrf = mrf + r12 * r12 (ssi);
    r15 = min(r15, r12);
    r0 = _mtr_acc_C1_MTR_28;
    call _mtr_flush;
    rts;
